//! CI entry point for the personal-data classification gate.
//!
//! One of two checks; the other is
//! `every_application_column_is_classified_or_its_table_is_declared` in
//! `backend/crates/platform/db/tests/personal_data_classification.rs`. Neither
//! subsumes the other — the crate doc in `lib.rs` says which cases each one
//! alone can see.
//!
//! `--inventory` prints the parsed table/column set and is how the baseline is
//! produced. The baseline is therefore generated by the same parser that
//! enforces it: a second, hand-maintained inventory would be free to disagree
//! with the gate about what a column is.

use std::path::Path;

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let workspace_dir = match std::env::current_dir() {
        Ok(dir) => dir,
        Err(e) => {
            eprintln!("ERROR: cannot determine cwd: {e}");
            std::process::exit(1);
        }
    };

    match args.first().map(String::as_str) {
        Some("--inventory") => inventory(&workspace_dir),
        Some("--citations") => citations(),
        Some(other) => {
            eprintln!("ERROR: unknown argument '{other}' (expected --inventory or --citations)");
            std::process::exit(2);
        }
        None => run_gate(&workspace_dir),
    }
}

fn run_gate(start_dir: &Path) {
    // Print the RESOLVED root, not the cwd. CI runs this with cwd `backend/`,
    // and a message naming a directory the gate did not actually scan is how a
    // scan-root bug hides.
    let root =
        console_gate_personal_data_classification::workspace_root(start_dir).unwrap_or_else(|e| {
            eprintln!("ERROR: {e}");
            std::process::exit(1);
        });
    eprintln!(
        "console-gate-personal-data-classification: checking workspace at {}",
        root.display()
    );

    let result =
        console_gate_personal_data_classification::check_workspace(&root).unwrap_or_else(|e| {
            eprintln!("ERROR: {e}");
            std::process::exit(1);
        });

    eprintln!(
        "console-gate-personal-data-classification: {} table(s), {} column(s); \
         {} column(s) classified; {} table(s) still baselined; \
         {} statement(s) unreadable and waived",
        result.total_tables,
        result.total_columns,
        result.classified_columns,
        result.baselined_tables,
        result.waived_statements
    );

    if result.passed() {
        eprintln!("console-gate-personal-data-classification: PASSED");
        std::process::exit(0);
    }

    eprintln!(
        "console-gate-personal-data-classification: FAILED - {} violation(s):",
        result.violations.len()
    );
    for violation in &result.violations {
        eprintln!("  {violation}");
    }
    std::process::exit(1);
}

fn inventory(start_dir: &Path) {
    let root =
        console_gate_personal_data_classification::workspace_root(start_dir).unwrap_or_else(|e| {
            eprintln!("ERROR: {e}");
            std::process::exit(1);
        });
    let files = console_gate_personal_data_classification::collect_migration_files(&root)
        .unwrap_or_else(|e| {
            eprintln!("ERROR: {e}");
            std::process::exit(1);
        });
    let schema = console_gate_personal_data_classification::parse_schema(&files);
    for (table, columns) in &schema.tables {
        for column in columns {
            println!("{table}\t{column}");
        }
    }
    eprintln!(
        "{} table(s), {} column(s)",
        schema.tables.len(),
        schema.column_count()
    );
}

fn citations() {
    for entry in console_gate_personal_data_classification::VOCABULARY {
        println!(
            "{}\t{}\t{}\t시행 {}\t{}",
            entry.token,
            entry.instrument,
            entry.article,
            entry.effective,
            if entry.subtokens.is_empty() {
                "-".to_owned()
            } else {
                entry.subtokens.join("|")
            }
        );
    }
}
